from collections import Counter

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_wcd(pairs):
    min_factors = [math.inf] * 10**9
    max_factors = [-1] * 10**9

    for a, b in pairs:
        ga = gcd(a, b)
        fa = []
        for i in range(2, int(math.sqrt(ga)) + 1):
            if ga % i == 0:
                fa.append(i)
                if ga // i != i:
                    fa.append(ga // i)

        fa_counter = Counter(fa)

        for f, count in fa_counter.items():
            if count > min_factors[f]:
                min_factors[f] = count
                if count >= 2:
                    max_factors[f] = f

    wcds = [f for f in range(2, 10**9) if all(min_factors[f] <= max_factors[other_f] for other_f in range(2, 10**9))]

    return -1 if not wcds else min(wcds)

