import math
from typing import List

def calculate_wcd(pairs: List[List[int]]) -> int:
    def gcd(a: int, b: int) -> int:
        return a if b == 0 else gcd(b, a % b)

    current_gcd = None
    for a, b in pairs:
        local_gcd = gcd(a, b)
        if current_gcd is None:
            current_gcd = local_gcd
        elif current_gcd > local_gcd:
            current_gcd //= math.gcd(current_gcd, local_gcd)

    return current_gcd if current_gcd > 1 else -1

