import math
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_wcd(pairs):
    min_factors = defaultdict(int)

    for a, b in pairs:
        ga = gcd(a, b)
        fa = {}
        fb = {}

        # Factorize a
        temp_a = a
        for i in range(2, int(math.sqrt(temp_a)) + 1):
            count = 0
            while temp_a % i == 0:
                temp_a //= i
                count += 1
            if count > 0:
                fa[i] = max(fa.get(i, 0), count)

        if temp_a > 1:
            fa[temp_a] = max(fa.get(temp_a, 0), 1)

        # Factorize b
        temp_b = b
        for i in range(2, int(math.sqrt(temp_b)) + 1):
            count = 0
            while temp_b % i == 0:
                temp_b //= i
                count += 1
            if count > 0:
                fb[i] = max(fb.get(i, 0), count)

        if temp_b > 1:
            fb[temp_b] = max(fb.get(temp_b, 0), 1)

        # Update minimum factors
        for prime, exp in fa.items():
            min_factors[prime] = max(min_factors[prime], exp)
        for prime, exp in fb.items():
            min_factors[prime] = max(min_factors[prime], exp)

    # Calculate the WCD
    wcd = 1
    for prime, exp in min_factors.items():
        wcd *= prime ** exp

    return wcd if wcd > 1 else -1

